<?php
require_once __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/spec.php';$u=require_login();$pdo=db_connect();$id=(int)($_GET['id']??0);
$st=$pdo->prepare('SELECT * FROM t_qc_inspection WHERE id=?');$st->execute([$id]);$ins=$st->fetch();if(!$ins){http_response_code(404);exit('Inspection not found.');}
if(!in_array($ins['inspection_type'],['INCOMING','INPROCESS'],true)){http_response_code(404);exit('Inspection not found.');}
if($ins['inspection_type']==='INPROCESS')require_permission('rawform');
if($ins['inspection_type']==='INCOMING'){header('Location: IncomingForm.php?id='.$id);exit;}
$rr=$pdo->prepare('SELECT * FROM t_qc_result WHERE inspection_id=? ORDER BY attempt_no,id');$rr->execute([$id]);$all=$rr->fetchAll();$attempts=[];foreach($all as $r)$attempts[(int)$r['attempt_no']][]=$r;
$profile=!empty($ins['spec_profile_id'])?get_spec_profile_by_id($pdo,(int)$ins['spec_profile_id']):get_spec_profile($pdo,$ins['entity_type'],(int)$ins['entity_id'],$ins['spec_type'],$ins['factory'],$ins['supplier']);
$attachments=[];if(table_exists($pdo,'t_qc_attachment')){$fa=$pdo->prepare("SELECT id,attachment_category,original_name,mime_type,file_size,uploaded_by_badge,uploaded_at FROM t_qc_attachment WHERE entity_type='INSPECTION' AND entity_id=? ORDER BY id");$fa->execute([$id]);$attachments=$fa->fetchAll();}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($ins['inspection_no'])?> | QACHEM</title><?php include 'include/mainstyle.php';include 'include/mainjs.php';?></head><body><?php include 'include/mainnavbar.php';?><main class="page"><div class="page-head"><div><h1><?=e($ins['inspection_no'])?></h1><div class="muted"><?=e($ins['inspection_type'])?> · <?=e($ins['chemical_name'])?> · <?=e($ins['batch_no'])?></div></div><div class="actions"><span class="badge <?=strtolower(str_replace(' ','-',$ins['status']))?>"><?=e($ins['status'])?></span><span class="badge <?=strtolower($ins['final_disposition']?:$ins['proposed_disposition']?:$ins['overall_disposition']?:'pending')?>"><?=e($ins['final_disposition']?:$ins['proposed_disposition']?:$ins['overall_disposition']?:'PENDING')?></span><button class="btn" onclick="window.print()">Print</button></div></div>
<div class="card"><div class="grid cols-4"><div><small class="muted">Specification</small><div><strong><?=e($profile?($profile['spec_type'].' · '.($profile['revision']?:'No revision').' · #'.$profile['id']):'—')?></strong></div></div><div><small class="muted">Inspection Date</small><div><strong><?=e($ins['inspection_at'])?></strong></div></div><div><small class="muted">Plant · Factory / Supplier</small><div><strong><?=e(($ins['plant']?$ins['plant'].' · ':'').($ins['factory']?:$ins['supplier']))?></strong></div></div><div><small class="muted">Sampling Location</small><div><strong><?=e($ins['sampling_location']?:$ins['tank_no'])?></strong></div></div><div><small class="muted">Tested By</small><div><strong><?=e($ins['tested_by_name']?:$ins['created_by_name'])?></strong></div></div><div><small class="muted">Verified By</small><div><strong><?=e($ins['verified_by_name']?:'—')?></strong></div></div><div><small class="muted">Manufacturing Date</small><div><?=e($ins['manufacturing_date']?:'—')?></div></div><div><small class="muted">Received / Expiry</small><div><?=e($ins['received_date']?:'—')?> / <?=e($ins['expiry_date']?:'—')?></div></div><div><small class="muted">Packaging</small><div><?=e($ins['packaging_condition']?:'—')?></div></div><?php if($ins['inspection_type']==='RETURN'):?><div><small class="muted">COA Reference</small><div><?=e($ins['coa_reference']?:'—')?></div></div><?php endif;?></div><?php if($ins['remarks']):?><div class="alert warn" style="margin-top:14px"><?=nl2br(e($ins['remarks']))?></div><?php endif;?></div>
<div class="section-title no-print"><h2>Supporting Evidence</h2><span class="muted">JPG, PNG, WEBP or PDF · max 8 MB</span></div><div class="card no-print evidence-card"><div class="evidence-upload"><label>Upload evidence<input type="file" id="inspectionFiles" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></label><button class="btn primary" type="button" onclick="uploadInspectionFiles()">Upload Evidence</button><span id="fileState" class="muted"></span></div><div class="evidence-list" id="evidenceList"><?php if(!$attachments):?><div class="empty evidence-empty">No evidence uploaded yet.</div><?php else:foreach($attachments as $f):?><div class="evidence-item" data-attachment-id="<?=e($f['id'])?>"><div><strong><?=e($f['original_name'])?></strong><span><?=e($f['attachment_category']?:'GENERAL')?> · <?=e(round(((int)$f['file_size'])/1024,1))?> KB · <?=e($f['uploaded_at'])?></span></div><div class="actions"><a class="btn small" target="_blank" href="attachment.php?id=<?=e($f['id'])?>">View</a><button class="btn small danger" type="button" onclick="removeEvidence(<?=e($f['id'])?>)">Remove</button></div></div><?php endforeach;endif;?></div></div>
<?php foreach($attempts as $n=>$rows):?><div class="section-title"><h2><?= $n===1?'Original Test':'Retest '.($n-1) ?></h2><span class="muted"><?=count($rows)?> parameter(s)</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Parameter</th><th>Result</th><th>Unit</th><th>Samples / Raw Inputs</th><th>Disposition</th><th>Recorded By</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):$raw=json_decode($r['raw_input_json']??'{}',true)?:[];?><tr><td><strong><?=e($r['parameter_name'])?></strong></td><td><?=e($r['result_value']!==null?number_format((float)$r['result_value'],2,'.',''):$r['result_text'])?></td><td><?=e($r['unit'])?></td><td class="spec-ref"><?=e(isset($raw['samples'])?implode(', ',array_filter($raw['samples'],fn($x)=>$x!=='')): '')?></td><td><span class="badge <?=strtolower($r['disposition'])?>"><?=e($r['disposition'])?></span></td><td><?=e($r['created_by_name'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php endforeach;?>
</main><?php include 'include/mainfooter.php';?>
<script>
async function uploadInspectionFiles(){const input=document.getElementById('inspectionFiles'),state=document.getElementById('fileState');if(!input.files.length){state.textContent='Choose at least one file.';return}state.textContent='Uploading...';try{for(const f of input.files){const fd=new FormData();fd.append('entity_type','INSPECTION');fd.append('entity_id',<?=json_encode($id)?>);fd.append('category','INSPECTION');fd.append('file',f);const r=await fetch('api/attachment.php',{method:'POST',headers:{'X-CSRF-Token':window.QACHEM_CSRF},body:fd});const j=await r.json();if(!j.success)throw new Error(j.message)}location.reload()}catch(e){state.textContent=e.message}}
async function removeEvidence(id){if(!confirm('Remove this evidence file?'))return;const state=document.getElementById('fileState');state.textContent='Removing...';try{const r=await fetch('api/attachment.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':window.QACHEM_CSRF},body:JSON.stringify({action:'delete',id})});const j=await r.json();if(!j.success)throw new Error(j.message);document.querySelector(`[data-attachment-id="${id}"]`)?.remove();if(!document.querySelector('.evidence-item'))document.getElementById('evidenceList').innerHTML='<div class="empty evidence-empty">No evidence uploaded yet.</div>';state.textContent='Evidence removed.'}catch(e){state.textContent=e.message}}
</script></body></html>
